/**
 * Builds a fast lookup map from lowercased/normalized alias to BibleBook
 */
const ALIAS_LOOKUP = new Map<string, BibleBook>();

// Normalize string: lowercase, collapse multiple spaces, replace smart hyphens
export function normalizeAlias(input: string): string {
  return input
    .toLowerCase()
    .normalize('NFC')
    .replace(/[\u2010\u2011\u2012\u2013\u2014\u2015]/g, '-')
    .replace(/\s+/g, ' ')
    .trim();
}

for (const book of BIBLE_BOOKS) {
  // Map standard name and shortName
  ALIAS_LOOKUP.set(normalizeAlias(book.name), book);
  ALIAS_LOOKUP.set(normalizeAlias(book.shortName), book);
  ALIAS_LOOKUP.set(normalizeAlias(book.osis), book);

  // Map all aliases
  for (const alias of book.aliases) {
    ALIAS_LOOKUP.set(normalizeAlias(alias), book);
  }
}

export function findBookByAlias(alias: string): BibleBook | undefined {
  return ALIAS_LOOKUP.get(normalizeAlias(alias));
}
